    {
      "card_ids": ["C03"],
      "claim": "Nicotinic acid showed about 90% systemic availability in humans, providing additional human evidence that small polar drugs can be highly orally bioavailable.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, including structurally related triazole/azole drugs with high assay-transfer scores, reports oral bioavailability well above 20% (36–100%). The query is a triazole aromatase inhibitor expected to be highly orally bioavailable; predict high.",
